module d_flip_flop_tb;
    reg clk;
    reg reset;
    reg d;
    wire q;

    d_flip_flop uut (
        .clk(clk),
        .reset(reset),
        .d(d),
        .q(q)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        // Initialize inputs
        reset = 1;
        d = 0;
        #20;

        // Test case 1: Reset test
        reset = 1;
        d = 1;
        #10;
        if (q !== 0) $fatal(1, "Test case 1 failed: Reset not working");

        // Test case 2: Normal operation
        reset = 0;
        d = 1;
        #10;
        if (q !== 1) $fatal(1, "Test case 2 failed: Q not following D");

        // Test case 3: Data change
        d = 0;
        #10;
        if (q !== 0) $fatal(1, "Test case 3 failed: Q not updating");

        // Test case 4: Reset during operation
        d = 1;
        #5;
        reset = 1;
        #5;
        if (q !== 0) $fatal(1, "Test case 4 failed: Reset not overriding D");

        $display("All test cases passed!");
        $finish;
    end
endmodule"}

